import{_ as t,o,c as i,ae as n}from"./chunks/framework.Dn6zxbF8.js";const u=JSON.parse('{"title":"License Files Follow Licensee Detection and the REUSE Layout","description":"","frontmatter":{"id":"8770665614","title":"License Files Follow Licensee Detection and the REUSE Layout","state":"Approved","created":"2026-08-22T00:00:00.000Z","tags":["licensing","repository","open-source","spdx"],"category":"General"},"headers":[],"relativePath":"adrs/8770665614/README.md","filePath":"adrs/8770665614/README.md"}'),s={name:"adrs/8770665614/README.md"};function r(a,e,c,l,d,h){return o(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="license-files-follow-licensee-detection-and-the-reuse-layout" tabindex="-1">License Files Follow Licensee Detection and the REUSE Layout <a class="header-anchor" href="#license-files-follow-licensee-detection-and-the-reuse-layout" aria-label="Permalink to &quot;License Files Follow Licensee Detection and the REUSE Layout&quot;">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>A repository states its license by putting the license text in a file, and every consumer downstream reads that statement mechanically. GitHub&#39;s license badge, the &quot;License&quot; line on a repository page, and the license field of the GitHub API are produced by <a href="https://github.com/licensee/licensee" target="_blank" rel="noreferrer">Licensee</a>, which scores candidate filenames and then compares the contents against the <a href="https://choosealicense.com" target="_blank" rel="noreferrer">choosealicense.com</a> corpus at a default confidence threshold of 98%. Compliance tooling in the wider ecosystem reads the <a href="https://reuse.software/spec-3.3/" target="_blank" rel="noreferrer">REUSE</a> layout instead, which is a different set of files in a different place.</p><p>The two are not variants of one convention, and each is unforgiving in a way that is invisible from inside the repository. Licensee scores files in the project root against a fixed table: <code>LICENSE</code> scores 1.00, <code>LICENSE.md</code> 0.95, <code>COPYING</code> 0.90, <code>LICENSE-MIT</code> 0.70. It also scans the top-level <code>LICENSES/</code> directory, where a filename in SPDX identifier format with a <code>.txt</code>, <code>.md</code>, <code>.markdown</code>, or <code>.html</code> extension scores 1.00 and anything else scores 0.00. A file named <code>LICENSES/MIT</code> with no extension is not seen at all.</p><p>The failure that matters is quieter than a missing file. Licensee resolves the project license by collecting every matched file, mapping each to a license, and taking the unique set. One license, and that license is reported. More than one, and the answer becomes the pseudo-license <code>other</code>, which is what a repository reading &quot;View license&quot; instead of &quot;MIT license&quot; is telling you. A repository with <code>LICENSE-MIT</code> and <code>LICENSE-APACHE</code> at its root has published two files and communicated nothing machine-readable. Because the set is deduplicated by license rather than by file, the same license in two places is not a conflict: <code>LICENSE</code> and <code>LICENSES/MIT.txt</code> both matching MIT collapse to one entry and report MIT.</p><p>REUSE governs the other half. Each license under which any covered file is licensed <strong>MUST</strong> have a file at <code>LICENSES/&lt;SPDX-License-Identifier&gt;.&lt;ext&gt;</code> in plain text, a license absent from the SPDX License List <strong>MUST</strong> use a <code>LicenseRef-[idstring]</code> identifier, the directory <strong>MUST NOT</strong> contain anything else, and it <strong>MUST NOT</strong> carry licenses nothing in the project uses. REUSE also says, in as many words, that a project <strong>MAY</strong> keep <code>COPYING</code> or <code>LICENSE</code> files &quot;for compliance with other standards, conventions, or tools&quot;, and that the REUSE tool ignores them.</p><p>That sentence is the whole design. The two conventions do not compete for the same file; they ask for different files, and satisfying both costs one duplicated license text.</p><p>Two naming hazards sit next to this decision, close enough in spelling to be mistaken for each other:</p><ul><li><code>Unlicense</code> is the SPDX identifier of <a href="https://spdx.org/licenses/Unlicense.html" target="_blank" rel="noreferrer">The Unlicense</a>, a public domain dedication. It grants everything. It is the opposite of reserving rights, and the filename <code>UNLICENSE</code> scores 1.00 in Licensee&#39;s root table by the same regex that matches <code>LICENSE</code>, so the file is read, not skipped.</li><li><code>UNLICENSED</code> is npm&#39;s string for the <code>license</code> field of <code>package.json</code>, documented for the case where you &quot;do not wish to grant others the right to use a private or unpublished package under any terms&quot;. It is not an SPDX identifier, it is not a license text, and it names the opposite condition from the identifier it nearly spells.</li></ul><h3 id="considered-options" tabindex="-1">Considered options <a class="header-anchor" href="#considered-options" aria-label="Permalink to &quot;Considered options&quot;">​</a></h3><p><strong>Root file only.</strong> Keep <code>LICENSE</code> and nothing else.</p><ul><li>Good, because it is what Licensee scores highest and what most repositories already have.</li><li>Bad, because a repository under more than one license has no non-ambiguous way to say so. Every root-level scheme for expressing the second license (<code>LICENSE-MIT</code>, <code>COPYING.CC-BY</code>, <code>MIT-LICENSE</code>) is scored as a separate candidate, so the project license degrades to <code>other</code>.</li><li>Bad, because REUSE tooling reports the project as non-compliant, and the root file is explicitly ignored by it.</li></ul><p><strong><code>LICENSES/</code> only.</strong> Adopt REUSE and drop the root file.</p><ul><li>Good, because it is sufficient for REUSE compliance and expresses any number of licenses without ambiguity.</li><li>Bad, because it discards the strongest convention there is. The root <code>LICENSE</code> file is what a human opens, what most licenses require be distributed with the software, and what tools older than REUSE look for.</li><li>Bad, because the top-level answer then depends on the <code>LICENSES/</code> scan, which several consumers of license metadata do not implement.</li></ul><p><strong>Root file, plus <code>LICENSES/</code> once a second license appears.</strong></p><ul><li>Good, because a single-licensed project keeps the one file every tool and reader already looks for, with no copy that can drift from it.</li><li>Good, because Licensee deduplicates by license, so adding <code>LICENSES/</code> to a project changes nothing about how its primary license is reported.</li><li>Good, because REUSE ignores the root file by specification, so the two layouts cannot invalidate each other.</li><li>Good, because a multi-licensed project gets one place, <code>LICENSES/</code>, that lists every license in use in a form no tool has to guess at.</li><li>Bad, because the primary license text exists twice in a multi-licensed project and the two copies can drift. Rule 7 below handles that.</li><li>Bad, because a single-licensed project is not REUSE compliant until it adds <code>LICENSES/&lt;SPDX-License-Identifier&gt;.txt</code>.</li><li>Bad, because a multi-licensed project still reports <code>other</code> as its top-line license, except for the LGPL pair from rule 5. That is an accurate summary rather than a defect, and no layout avoids it.</li></ul><h2 id="resolution" tabindex="-1">Resolution <a class="header-anchor" href="#resolution" aria-label="Permalink to &quot;Resolution&quot;">​</a></h2><p>Chosen option: root file, plus <code>LICENSES/</code> once a second license appears, because a single license is fully stated by the root file, and the duplicate only earns its maintenance cost when there is more than one license to list.</p><ol><li>Every repository <strong>MUST</strong> have a <code>LICENSE</code> file in its root, with no extension, containing the verbatim text of its primary license. The primary license is the one covering the source code; where a repository is mostly prose, it is the one covering the prose.</li><li>A repository distributed under more than one license <strong>MUST</strong> have a top-level <code>LICENSES/</code> directory containing one file per license and per license exception under which any part of the repository is distributed, including the primary license. Filenames <strong>MUST</strong> be <code>&lt;SPDX-License-Identifier&gt;.txt</code>, spelled exactly as the <a href="https://spdx.org/licenses/" target="_blank" rel="noreferrer">SPDX License List</a> or the <a href="https://spdx.org/licenses/exceptions-index.html" target="_blank" rel="noreferrer">SPDX License Exceptions List</a> spells it, with verbatim text. A repository distributed under <code>GPL-3.0-only WITH Classpath-exception-2.0</code> carries both <code>LICENSES/GPL-3.0-only.txt</code> and <code>LICENSES/Classpath-exception-2.0.txt</code>. Licensee validates the identifier&#39;s shape and not its existence, so <code>Apache2.0.txt</code> scores as high as <code>Apache-2.0.txt</code> and no tool reports the typo.</li><li>Within <code>LICENSES/</code>, terms not on the SPDX License List <strong>MUST</strong> use <code>LICENSES/LicenseRef-&lt;idstring&gt;.txt</code>. This is the only correct way to declare proprietary or all-rights-reserved terms, and the file holds the actual terms.</li><li><code>Unlicense</code> <strong>MUST NOT</strong> be used to mean &quot;not licensed&quot; or &quot;proprietary&quot;, and no file named <code>UNLICENSE</code> <strong>MAY</strong> be added for that purpose. It is a public domain dedication; adding it dedicates the work to the public domain, which is the reverse of the intent. A repository deliberately dedicating to the public domain uses it correctly, as <code>LICENSE</code>.</li><li>No other license-bearing filename <strong>MAY</strong> appear in the repository root: not <code>LICENSE.md</code>, <code>LICENCE</code>, <code>COPYING</code>, <code>LICENSE-MIT</code>, <code>MIT-LICENSE</code>, <code>OFL</code>, or <code>PATENTS</code>. Each is scored as an independent candidate, and a second distinct license among them turns the project license into <code>other</code>. A license whose own instructions mandate a filename is the exception: LGPL is distributed as <code>COPYING.lesser</code> beside <code>COPYING</code>, and Licensee has a dedicated rule for that pair. <code>COPYRIGHT</code> is permitted, because Licensee excludes it when deciding whether a project is multi-licensed.</li><li><code>LICENSES/</code> <strong>MUST NOT</strong> contain anything but license and license exception files, and <strong>MUST NOT</strong> contain a license or exception nothing in the repository uses. Removing one from the repository removes its file.</li><li>Where <code>LICENSES/</code> exists, the root <code>LICENSE</code> and its counterpart in <code>LICENSES/</code> <strong>MUST</strong> hold the same text. Where the license carries placeholder fields, the year and holder are filled in identically in both. No other edit to license text is permitted: Licensee matches at 98% similarity, and an edited text falls to <code>other</code>.</li><li>Where a package manifest has a <code>license</code> field, it <strong>MUST</strong> carry an SPDX expression naming exactly the licenses the repository carries (<code>&quot;MIT&quot;</code>, <code>&quot;MIT AND CC-BY-4.0&quot;</code>, <code>&quot;MIT OR Apache-2.0&quot;</code>), except for npm&#39;s <code>&quot;UNLICENSED&quot;</code> as described below, and <code>SPDX-License-Identifier</code> headers <strong>SHOULD</strong> be used to attribute individual files where a repository is multi-licensed. npm&#39;s <code>&quot;UNLICENSED&quot;</code> is an npm-only string, not an SPDX identifier: it is correct in <code>package.json</code> for a package that grants no rights, and <strong>MUST NOT</strong> be written into a license file or a <code>SPDX-License-Identifier</code> header, where rule 3 applies instead.</li><li>A repository under exactly one license <strong>MUST NOT</strong> have a <code>LICENSES/</code> directory. The root <code>LICENSE</code> already states the license, and a second copy only adds a file that can drift from it. The directory appears with the second license, holding both.</li></ol><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Single-licensed repositories need nothing beyond the root <code>LICENSE</code> and report the same license as before.</li><li>Multi-licensed repositories report <code>other</code> as their top-line license and list every match in the licenses array. The exception is the LGPL pair from rule 5: Licensee reports the LGPL license when exactly an LGPL and a GPL file match, in that order. This is the honest answer, and the <code>LICENSES/</code> directory is where the detail lives.</li><li>Repositories currently using <code>LICENSE.md</code> or <code>COPYING</code> rename to <code>LICENSE</code>. The rename is the whole migration for a single-licensed repository.</li><li>Repositories with root-level <code>LICENSE-&lt;ID&gt;</code> files move each one to <code>LICENSES/&lt;SPDX-ID&gt;.txt</code> and put the primary license in <code>LICENSE</code>.</li><li>REUSE tooling can be run against any multi-licensed repository following this rule without further layout work. A single-licensed repository does not pass REUSE, which is accepted: no tool this decision relies on needs more than the root <code>LICENSE</code> to report a single license. The remaining work for full REUSE compliance is per-file licensing information, which rule 8 asks for as a <strong>SHOULD</strong> rather than adopting REUSE wholesale.</li><li>In a multi-licensed repository the duplicated primary license is a maintenance obligation. It is one file that changes only when the license changes, which is rare enough that rule 7 is cheaper than either convention&#39;s absence.</li><li>This repository is itself affected: it distributes prose under CC-BY-4.0 and code samples under MIT, and currently declares that split only in prose in the README. Under this decision it carries <code>LICENSES/CC-BY-4.0.txt</code> and <code>LICENSES/MIT.txt</code> alongside the existing MIT <code>LICENSE</code>, and its detected license becomes <code>other</code>.</li></ul><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h2><ul><li><a href="https://github.com/licensee/licensee/blob/main/docs/what-we-look-at.md" target="_blank" rel="noreferrer">Licensee: What we look at</a></li><li><a href="https://github.com/licensee/licensee/blob/main/lib/licensee/project_files/license_file.rb" target="_blank" rel="noreferrer">Licensee: license file filename scoring</a></li><li><a href="https://github.com/licensee/licensee/blob/main/lib/licensee/projects/project.rb" target="_blank" rel="noreferrer">Licensee: project license resolution</a></li><li><a href="https://reuse.software/spec-3.3/" target="_blank" rel="noreferrer">REUSE Specification v3.3</a></li><li><a href="https://spdx.org/licenses/" target="_blank" rel="noreferrer">SPDX License List</a></li><li><a href="https://spdx.github.io/spdx-spec/v2.3/other-licensing-information-detected/" target="_blank" rel="noreferrer">SPDX: Other licensing information detected (<code>LicenseRef-</code>)</a></li><li><a href="https://spdx.org/licenses/Unlicense.html" target="_blank" rel="noreferrer">The Unlicense (SPDX <code>Unlicense</code>)</a></li><li><a href="https://docs.npmjs.com/cli/v11/configuring-npm/package-json#license" target="_blank" rel="noreferrer">npm <code>package.json</code> license field</a></li><li><a href="https://docs.github.com/en/repositories/managing-your-repositorys-settings-and-features/customizing-your-repository/licensing-a-repository" target="_blank" rel="noreferrer">GitHub: Licensing a repository</a></li></ul>',23)])])}const f=t(s,[["render",r]]);export{u as __pageData,f as default};
